function executeScript(event) {
  // JS-BuildConnectorInput: builds the ExecuteCustomQuery input for task 2.
  // quarter 0 means "all quarters" and is sent to the query as NULL.
  var quarter = Number(event.getParameter("quarter"));
  var quarterParam = (!quarter) ? null : quarter;
  var payload = {
    query: "SELECT quarter, year, actual, load_time\n" +
      "FROM kpi_records\n" +
      "WHERE kpi_code = ?\n" +
      "  AND year = ?\n" +
      "  AND (CAST(? AS SMALLINT) IS NULL OR quarter = ?)\n" +
      "ORDER BY quarter",
    queryParameters: [
      { value: String(event.getParameter("kpiCode")), dataType: "VARCHAR" },
      { value: Number(event.getParameter("year")), dataType: "INTEGER" },
      { value: quarterParam, dataType: "INTEGER" },
      { value: quarterParam, dataType: "INTEGER" }
    ],
    timeout: 30,
    maxRows: 10
  };
  event.setParameter("`Task_2_connectorInputPayload`", payload);
}

function executeScript(event) {
  // JS-TransformOutput: maps connector rows to the OAS KpiRecord shape.
  // Output is always an array ([] when there are no rows), never null.
  function toIsoUtc(value) {
    var d;
    if (typeof value === "number") {
      d = new Date(value);
    } else {
      var s = String(value).trim()
        .replace(/^(\d{4}-\d{2}-\d{2})[ T]/, "$1T")
        .replace(/(T\d{2}:\d{2}:\d{2})\.\d+/, "$1")
        .replace(/([+-]\d{2})$/, "$1:00")
        .replace(/([+-]\d{2})(\d{2})$/, "$1:$2");
      if (!/(Z|[+-]\d{2}:\d{2})$/i.test(s)) {
        s = s + "Z";
      }
      d = new Date(s);
    }
    if (isNaN(d.getTime())) {
      throw new Error("Invalid load_time value from connector: " + value);
    }
    return d.toISOString().replace(/\.\d{3}Z$/, "Z");
  }

  var rows = event.getParameter("`Task_2_connectorOutputPayload`");
  if (typeof rows === "string") {
    rows = rows.trim() === "" ? [] : JSON.parse(rows);
  }
  if (rows === null || rows === undefined) {
    rows = [];
  }
  if (!Array.isArray(rows)) {
    throw new Error("Connector output is not an array");
  }
  var data = rows.map(function (r) {
    return {
      quarter: Number(r.quarter),
      year: Number(r.year),
      actual: Number(r.actual),
      loadTime: toIsoUtc(r.load_time)
    };
  });
  // A JSON_VALUE variable rejects a bare JS array ("is not a Json value"), so set the
  // JSON text of the array; the variable then holds the array itself.
  event.setParameter("data", JSON.stringify(data));
}
